use super::super::data::SurfaceData;
use glam::{Mat4, Vec3};

pub(super) fn edge_function(a: Vec3, b: Vec3, c: Vec3) -> f32 {
    (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x)
}

pub(super) fn project_world_to_screen(
    view_projection: Mat4,
    world_pos: Vec3,
    width: f32,
    height: f32,
) -> Option<Vec3> {
    let clip_pos = view_projection * world_pos.extend(1.0);
    if clip_pos.w <= 1e-6 {
        return None;
    }

    let ndc = clip_pos.truncate() / clip_pos.w;
    if !(0.0..=1.0).contains(&ndc.z) {
        return None;
    }

    let x = (ndc.x + 1.0) * 0.5 * width;
    let y = (1.0 - ndc.y) * 0.5 * height;
    Some(Vec3::new(x, y, ndc.z))
}

pub(super) fn default_frequency_ticks() -> Vec<f64> {
    vec![
        100.0, 200.0, 500.0, 1000.0, 2000.0, 5000.0, 10000.0, 20000.0,
    ]
}

pub(super) fn log_frequency_minor_ticks(data: &SurfaceData) -> Vec<f64> {
    let min = if data.x_min > 0.0 {
        data.x_min
    } else {
        data.x_values
            .iter()
            .copied()
            .filter(|value| *value > 0.0 && value.is_finite())
            .fold(f64::INFINITY, f64::min)
    };
    let max = data.x_max;
    if !min.is_finite() || !max.is_finite() || min <= 0.0 || max <= min {
        return Vec::new();
    }

    let start_decade = min.log10().floor() as i32;
    let end_decade = max.log10().ceil() as i32;
    let mut ticks = Vec::new();
    for decade in start_decade..=end_decade {
        let base = 10_f64.powi(decade);
        for multiplier in 2..10 {
            let value = base * multiplier as f64;
            if value >= min && value <= max {
                ticks.push(value);
            }
        }
    }
    ticks
}

pub(super) fn sanitize_axis_positions(values: &mut Vec<f32>, min: f32, max: f32) {
    const EPS: f32 = 1e-4;
    values.retain(|value| value.is_finite() && *value > min + EPS && *value < max - EPS);
    values.sort_by(|a, b| a.total_cmp(b));
    values.dedup_by(|a, b| (*a - *b).abs() < EPS);
}

pub(super) fn remove_positions(values: &mut Vec<f32>, positions_to_remove: &[f32]) {
    const EPS: f32 = 1e-4;
    values.retain(|value| {
        !positions_to_remove
            .iter()
            .any(|position| (*value - *position).abs() < EPS)
    });
}
